fn normalize_manager_plan_risk(value: &str) -> Result<String, AppError> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "low" | "medium" | "high" => Ok(normalized),
        _ => Err(AppError::bad_request(
            "risk_classification must be one of low, medium, or high",
        )),
    }
}

fn normalize_manager_plan_status(value: &str) -> Result<String, AppError> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "planned" | "reviewed" | "approved" | "needs_changes" | "blocked" => Ok(normalized),
        _ => Err(AppError::bad_request(
            "manager agent plan status must be planned, reviewed, approved, needs_changes, or blocked",
        )),
    }
}

fn ensure_agent_handoff_transition(current: &str, next: &str) -> Result<(), AppError> {
    let allowed = matches!(
        (current, next),
        ("requested", "accepted")
            | ("requested", "rejected")
            | ("requested", "failed")
            | ("accepted", "completed")
            | ("accepted", "failed")
    );
    if allowed {
        Ok(())
    } else {
        Err(AppError::bad_request(format!(
            "cannot transition agent handoff from {current} to {next}"
        )))
    }
}

fn normalize_handoff_semantic_scopes(value: Value) -> Result<Value, AppError> {
    if value.is_object() {
        Ok(value)
    } else {
        Err(AppError::bad_request(
            "handoff semantic_scopes must be a JSON object",
        ))
    }
}

fn handoff_remote_computer_required(
    agent: &Agent,
    runtime_profile: Option<&AgentRuntimeProfile>,
) -> bool {
    agent
        .remote_computer_profile
        .get("required")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || runtime_profile.is_some_and(|profile| profile.remote_computer_required)
}

fn default_handoff_review_status(plan: Option<&ManagerAgentPlan>) -> &'static str {
    if plan.is_some_and(|plan| plan.status == "approved" || plan.status == "reviewed") {
        "manager_reviewed"
    } else {
        "pending_review"
    }
}

fn normalize_handoff_review_status(value: &str) -> Result<String, AppError> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "pending_review"
        | "manager_reviewed"
        | "human_review_required"
        | "approved"
        | "rejected" => Ok(normalized),
        _ => Err(AppError::bad_request(
            "review_status must be pending_review, manager_reviewed, human_review_required, approved, or rejected",
        )),
    }
}

fn normalize_handoff_human_escalation_status(value: &str) -> Result<String, AppError> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "none" | "required" | "requested" | "resolved" => Ok(normalized),
        _ => Err(AppError::bad_request(
            "human_escalation_status must be none, required, requested, or resolved",
        )),
    }
}

fn normalize_optional_text(value: String) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

fn default_handoff_assignment_message(
    handoff: &AgentHandoffEvent,
    plan: &ManagerAgentPlan,
    target_agent: &Agent,
) -> String {
    let goal = plan
        .task_intake
        .get("goal")
        .and_then(Value::as_str)
        .unwrap_or("Execute the assigned manager-agent handoff.");
    format!(
        "Manager Agent assigned this task to specialist agent {}.\n\nIntent: {}\nRisk: {}\nRemote Computer required: {}\n\nGoal: {}\n\nPayload:\n{}",
        target_agent.name,
        handoff.intent,
        handoff.risk_level,
        handoff.remote_computer_required,
        goal,
        handoff.payload
    )
}

fn validate_handoff_token(field: &str, value: &str) -> Result<String, AppError> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.len() > 128
        || !trimmed
            .chars()
            .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '-' || ch == '_')
    {
        return Err(AppError::bad_request(format!(
            "{field} must be a lowercase slug"
        )));
    }
    Ok(trimmed.to_string())
}

fn validate_handoff_schema_version(value: &str) -> Result<String, AppError> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.len() > 128
        || !trimmed
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '_' | '/'))
    {
        return Err(AppError::bad_request(
            "schema_version must be a non-empty schema identifier",
        ));
    }
    Ok(trimmed.to_string())
}

fn normalize_handoff_risk_level(value: &str) -> Result<String, AppError> {
    let normalized = value.trim().to_ascii_lowercase();
    if matches!(normalized.as_str(), "low" | "medium" | "high") {
        Ok(normalized)
    } else {
        Err(AppError::bad_request(
            "risk_level must be one of low, medium, or high",
        ))
    }
}

fn matching_handoff_rule<'a>(
    runtime_config: &'a Value,
    target_agent_id: Uuid,
    intent: &str,
    schema_version: &str,
    risk_level: &str,
    approval_required: bool,
) -> Result<&'a Value, AppError> {
    let rules = runtime_config
        .get("handoffs")
        .and_then(|handoffs| handoffs.get("allowed_targets"))
        .and_then(Value::as_array)
        .ok_or_else(|| {
            AppError::forbidden("source agent version has no handoff allowed_targets")
        })?;
    rules
        .iter()
        .find(|rule| {
            let rule_requires_approval =
                handoff_rule_bool(rule, "approval_required").unwrap_or(false);
            handoff_rule_target_id(rule) == Some(target_agent_id)
                && json_string_array_contains(rule.get("intents"), intent)
                && json_optional_string_array_contains(rule.get("schema_versions"), schema_version)
                && json_optional_string_array_contains(rule.get("risk_levels"), risk_level)
                && (!rule_requires_approval || approval_required)
        })
        .ok_or_else(|| {
            AppError::forbidden(
                "agent handoff target, intent, schema_version, risk_level, or approval requirement is not allowlisted",
            )
        })
}

fn handoff_rule_target_id(rule: &Value) -> Option<Uuid> {
    rule.get("target_agent_id")
        .or_else(|| rule.get("target_agent"))
        .and_then(Value::as_str)
        .and_then(|value| Uuid::parse_str(value).ok())
}

fn handoff_rule_bool(rule: &Value, key: &str) -> Option<bool> {
    rule.get(key).and_then(Value::as_bool)
}

fn json_string_array_contains(value: Option<&Value>, expected: &str) -> bool {
    value
        .and_then(Value::as_array)
        .is_some_and(|items| items.iter().any(|item| item.as_str() == Some(expected)))
}

fn json_optional_string_array_contains(value: Option<&Value>, expected: &str) -> bool {
    match value.and_then(Value::as_array) {
        Some(items) => items.iter().any(|item| item.as_str() == Some(expected)),
        None => true,
    }
}

fn validate_handoff_payload_schema(
    payload: &Value,
    schema: Option<&Value>,
) -> Result<(), AppError> {
    let Some(schema) = schema else {
        return Ok(());
    };
    if schema.get("type").and_then(Value::as_str) != Some("object") {
        return Err(AppError::bad_request(
            "handoff payload_schema must declare type object",
        ));
    }
    let Some(payload_object) = payload.as_object() else {
        return Err(AppError::bad_request(
            "handoff payload must be a JSON object",
        ));
    };
    if let Some(required) = schema.get("required").and_then(Value::as_array) {
        for key in required.iter().filter_map(Value::as_str) {
            if !payload_object.contains_key(key) {
                return Err(AppError::bad_request(format!(
                    "handoff payload missing required field {key}"
                )));
            }
        }
    }
    let Some(properties) = schema.get("properties").and_then(Value::as_object) else {
        return Ok(());
    };
    for (key, property_schema) in properties {
        let Some(value) = payload_object.get(key) else {
            continue;
        };
        let Some(expected_type) = property_schema.get("type").and_then(Value::as_str) else {
            continue;
        };
        let matches_type = match expected_type {
            "string" => value.is_string(),
            "number" => value.is_number(),
            "integer" => value.as_i64().is_some() || value.as_u64().is_some(),
            "boolean" => value.is_boolean(),
            "object" => value.is_object(),
            "array" => value.is_array(),
            _ => {
                return Err(AppError::bad_request(format!(
                    "unsupported handoff payload_schema type {expected_type}"
                )));
            }
        };
        if !matches_type {
            return Err(AppError::bad_request(format!(
                "handoff payload field {key} must be {expected_type}"
            )));
        }
    }
    Ok(())
}

async fn validate_workflow_pack_route(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<ValidateWorkflowPack>,
) -> Result<Json<workflow_pack::WorkflowPackValidationReport>, AppError> {
    authorize_request(&state, &headers, Permission::Admin, "workflow_pack", None).await?;
    let manifest_path = resolve_workflow_pack_manifest_path(&input.manifest_path)?;
    let report = workflow_pack::validate_workflow_pack_manifest_path(&manifest_path)
        .map_err(|error| AppError::bad_request(error.to_string()))?;
    Ok(Json(report))
}

