async fn enqueue_session_loop(
    state: &AppState,
    id: Uuid,
    trigger_event_id: Option<Uuid>,
    reason: &str,
) -> Result<SessionLoopJob, AppError> {
    if !session_accepts_worker_execution(state, id).await? {
        return Err(AppError::bad_request(
            "session is terminal and cannot enqueue session loop work",
        ));
    }
    let job = state
        .enqueue_session_loop_job(id, trigger_event_id, reason)
        .await?;
    state
        .append_event(
            "system",
            Some(job.id),
            id,
            "session.loop.queued",
            json!({
                "session_loop_job_id": job.id,
                "environment_id": job.environment_id,
                "reason": job.reason,
                "status": job.status
            }),
        )
        .await?;
    Ok(job)
}

async fn enqueue_session_loop_after_approval_event(
    state: &AppState,
    session_id: Uuid,
    trigger_event_id: Uuid,
    reason: &str,
) -> Result<SessionLoopJob, AppError> {
    set_managed_session_status(
        state,
        session_id,
        SessionStatus::Idle,
        "approval resolved; session loop queued",
    )
    .await?;
    enqueue_session_loop(state, session_id, Some(trigger_event_id), reason).await
}

async fn project_session_event_to_loop(
    state: &AppState,
    event: &SessionEvent,
) -> Result<Option<SessionLoopJob>, AppError> {
    let Some(reason) = session_loop_reason_for_event(&event.event_type) else {
        return Ok(None);
    };
    if matches!(
        event.event_type.as_str(),
        "approval.approved" | "approval.rejected" | "execution.completed"
    ) {
        set_managed_session_status(
            state,
            event.session_id,
            SessionStatus::Idle,
            "durable event projected to session loop",
        )
        .await?;
    }
    enqueue_session_loop(state, event.session_id, Some(event.id), reason)
        .await
        .map(Some)
}

async fn continue_session_after_approved_execution(
    state: &AppState,
    session_id: Uuid,
    job: Option<&ExecutionJob>,
    approval_event: Option<&SessionEvent>,
    reason: &str,
) -> Result<(), AppError> {
    let trigger_event = if let Some(job) = job {
        seed_session_loop_window_at_latest_tool_result(state, session_id, job.tool_call_id).await?;
        state
            .append_event(
                "worker",
                Some(job.id),
                session_id,
                "execution.completed",
                json!({
                    "execution_job_id": job.id,
                    "approval_id": job.approval_id,
                    "tool_call_id": job.tool_call_id,
                    "tool": job.tool_name,
                    "status": job.status,
                    "worker_id": job.worker_id,
                    "reason": reason
                }),
            )
            .await?
    } else if let Some(approval_event) = approval_event {
        approval_event.clone()
    } else {
        state
            .append_event(
                "system",
                None,
                session_id,
                "session.loop.resume_requested",
                json!({"reason": reason}),
            )
            .await?
    };
    if trigger_event.event_type == "session.loop.resume_requested" {
        enqueue_session_loop_after_approval_event(state, session_id, trigger_event.id, reason)
            .await?;
    } else {
        project_session_event_to_loop(state, &trigger_event).await?;
    };
    Ok(())
}

async fn seed_session_loop_window_at_latest_tool_result(
    state: &AppState,
    session_id: Uuid,
    tool_call_id: Uuid,
) -> Result<(), AppError> {
    let events = state.list_events(session_id).await?;
    if let Some(tool_result_event) = events.iter().rev().find(|event| {
        event.event_type == "tool.result"
            && event
                .payload
                .get("tool_call_id")
                .and_then(Value::as_str)
                .and_then(|value| Uuid::parse_str(value).ok())
                == Some(tool_call_id)
    }) {
        project_session_event_to_loop(state, tool_result_event).await?;
    }
    Ok(())
}

async fn run_session_loop(state: &AppState, job: &SessionLoopJob) -> Result<Session, AppError> {
    let id = job.session_id;
    if !session_accepts_worker_execution(state, id).await? {
        return Err(AppError::bad_request(
            "session is terminal and cannot run session loop work",
        ));
    }
    ensure_primary_session_thread(state, id).await?;
    set_managed_session_status(state, id, SessionStatus::Running, "session loop started").await?;
    state
        .append_audit_log(new_audit_log(
            Some(id),
            "system",
            None,
            "session.started",
            "session",
            Some(id),
            json!({"status": "running"}),
        ))
        .await?;

    let (provider_label, provider) = provider_client_for_session(&state, id).await?;
    let provider_response = run_provider_harness(
        &state,
        id,
        provider.as_ref(),
        &provider_label,
        job.pending_event_seq_start,
        job.pending_event_seq_end,
    )
    .await?;

    state
        .append_event(
            "agent",
            None,
            id,
            "agent.plan",
            json!({
                "steps": provider_response.plan
            }),
        )
        .await?;

    let mut waiting_for_approval = false;
    for tool_call in provider_response.tool_calls {
        let result = execute_tool_invocation(
            &state,
            &tool_call.tool_name,
            ExecuteTool {
                session_id: id,
                args: tool_call.args,
            },
            ToolInvocationOrigin::SessionLoop,
        )
        .await?;
        if result.get("status").and_then(Value::as_str) == Some("approval_required") {
            waiting_for_approval = true;
            break;
        }
    }

    let artifact = Artifact {
        id: Uuid::new_v4(),
        session_id: id,
        artifact_type: "markdown".to_string(),
        name: "diagnostics.md".to_string(),
        path: None,
        content: json!({
            "markdown": "# Runtime Diagnostics\n\nThe generic runtime processed recent platform events, confirmed approval gating for shell execution, and produced a replayable diagnostics artifact."
        }),
        created_at: Utc::now(),
    };
    let artifact = state.insert_artifact(artifact).await?;
    state
        .append_event(
        "system",
        Some(artifact.id),
        id,
        "artifact.created",
        json!({"artifact_id": artifact.id, "name": artifact.name, "artifact_type": artifact.artifact_type}),
    )
    .await?;
    state
        .append_audit_log(new_audit_log(
            Some(id),
            "system",
            None,
            "artifact.created",
            "artifact",
            Some(artifact.id),
            json!({"name": artifact.name, "artifact_type": artifact.artifact_type}),
        ))
        .await?;

    state
        .append_event(
        "agent",
        None,
        id,
            "llm.response",
            json!({
                "final_report": {
                "summary": "Generic Runtime Diagnostics Demo reached the approval gate and produced a replayable artifact.",
                "files_read": ["README.md", "config/policy.stage1.yaml"],
                "sql_tables": ["generic_demo.platform_events", "generic_demo.sample_documents", "generic_demo.sample_metrics"],
                "policy_events": ["policy.requires_approval for shell.exec"],
                "artifacts": ["diagnostics.md"],
                "next_steps": [
                    "Add live external provider transport behind the ProviderClient trait",
                    "Add Docker-backed sandbox execution for shell workers",
                    "Run Postgres-backed sql.query integration verification"
                ]
            }
        }),
    )
    .await?;

    if let Some(final_message) = provider_response.final_message {
        state
            .append_event(
                "agent",
                None,
                id,
                "agent.final",
                json!({"message": final_message}),
            )
            .await?;
    }

    let session = if waiting_for_approval {
        set_managed_session_status(
            state,
            id,
            SessionStatus::RequiresAction,
            "tool approval required",
        )
        .await?
    } else {
        let session =
            set_managed_session_status(state, id, SessionStatus::Idle, "provider tool loop idled")
                .await?;
        state
            .append_event(
                "system",
                None,
                id,
                "session.loop.idle",
                json!({"reason": "provider tool loop idled"}),
            )
            .await?;
        session
    };
    Ok(session)
}

