async fn execute_remote_computer_sidecar_recovery(
    state: &AppState,
) -> Result<RemoteComputerSidecarRecoveryRun, AppError> {
    execute_remote_computer_sidecar_recovery_with_lookup(state, |key| std::env::var(key).ok()).await
}

async fn execute_remote_computer_sidecar_recovery_with_lookup<F>(
    state: &AppState,
    lookup: F,
) -> Result<RemoteComputerSidecarRecoveryRun, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let targets = remote_computer_sidecar_recovery_targets(state).await?;
    let config = RemoteComputerRunnerConfig::from_env();
    let runner = remote_computer_runner_for_config(&config);
    let runner_readiness = runner.readiness(&config);
    let replacement_enabled = env_bool_lookup(
        "MANDOFORGE_REMOTE_COMPUTER_SIDECAR_REPLACEMENT_ENABLED",
        &lookup,
    );
    let validation_controller_required =
        remote_computer_sidecar_validation_controller_required(&lookup);
    let validation_controller_configured =
        remote_computer_sidecar_validation_controller_configured(&lookup);
    let live_replacement_enabled = replacement_enabled
        && runner_readiness.configured
        && runner_readiness.live_mutation_enabled
        && config.mutation_enabled
        && config.live_mutation_enabled
        && (!validation_controller_required || validation_controller_configured);
    let mut runner_responses = Vec::new();
    let mut attempted_replacement_count = 0;
    let mut blocked_replacement_count = 0;
    for target in &targets {
        let Some(pod_name) = target.pod_name.clone() else {
            blocked_replacement_count += 1;
            continue;
        };
        if !live_replacement_enabled {
            blocked_replacement_count += 1;
            continue;
        }
        let delete = runner
            .mutate(
                &config,
                RemoteComputerRunnerDryRunRequest {
                    operation: Some("live_delete".to_string()),
                    remote_computer_id: Some(target.remote_computer_id),
                    session_id: None,
                    pod_name: Some(pod_name.clone()),
                    metadata: Some(json!({
                        "reason": target.reason,
                        "sidecar_recovery": true,
                        "replacement_step": "delete_unhealthy_pod"
                    })),
                },
            )
            .await;
        attempted_replacement_count += 1;
        runner_responses.push(delete);
        let create = runner
            .mutate(
                &config,
                RemoteComputerRunnerDryRunRequest {
                    operation: Some("live_create".to_string()),
                    remote_computer_id: Some(target.remote_computer_id),
                    session_id: None,
                    pod_name: Some(pod_name),
                    metadata: Some(json!({
                        "reason": target.reason,
                        "sidecar_recovery": true,
                        "artifact_discovery_enabled": true,
                        "replacement_step": "create_replacement_pod"
                    })),
                },
            )
            .await;
        runner_responses.push(create);
    }
    let failed_attempts = runner_responses
        .iter()
        .filter(|response| !matches!(response.status.as_str(), "mutation_ok"))
        .count();
    let status = if targets.is_empty() {
        "noop"
    } else if !replacement_enabled {
        "blocked"
    } else if validation_controller_required && !validation_controller_configured {
        "blocked"
    } else if attempted_replacement_count == 0 {
        "blocked"
    } else if failed_attempts > 0 {
        "attention"
    } else {
        "completed"
    }
    .to_string();
    let message = if targets.is_empty() {
        "No unhealthy Remote Computer sidecars require recovery".to_string()
    } else if !replacement_enabled {
        "Sidecar recovery planned replacements but live replacement is blocked until MANDOFORGE_REMOTE_COMPUTER_SIDECAR_REPLACEMENT_ENABLED is enabled".to_string()
    } else if validation_controller_required && !validation_controller_configured {
        "Sidecar recovery planned replacements but live replacement is blocked until MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_URL is configured".to_string()
    } else if !live_replacement_enabled {
        "Sidecar recovery is enabled, but the Kubernetes runner live mutation gates are not fully open".to_string()
    } else if failed_attempts > 0 {
        "One or more Remote Computer sidecar replacement mutations failed".to_string()
    } else {
        "Remote Computer sidecar replacement run completed for unhealthy Pods".to_string()
    };
    let mut run = RemoteComputerSidecarRecoveryRun {
        generated_at: Utc::now(),
        status,
        replacement_enabled,
        validation_controller_required,
        validation_controller_configured,
        runner_status: runner_readiness.status,
        unhealthy_count: targets.len(),
        planned_replacement_count: targets
            .iter()
            .filter(|target| target.pod_name.is_some())
            .count(),
        attempted_replacement_count,
        blocked_replacement_count,
        targets,
        runner_responses,
        validation_result: json!({
            "attempted": false,
            "status": "skipped",
            "reason": if validation_controller_configured {
                "no_replacement_attempted"
            } else {
                "validation_controller_not_configured"
            }
        }),
        execution_enabled: false,
        message,
    };
    if validation_controller_configured && run.attempted_replacement_count > 0 {
        match execute_remote_computer_sidecar_validation_controller(&lookup, &run).await {
            Ok(validation) => {
                let validation_status = validation
                    .get("status")
                    .and_then(Value::as_str)
                    .unwrap_or("failed")
                    .to_string();
                run.validation_result = validation;
                if validation_status != "validated" && run.status == "completed" {
                    run.status = "attention".to_string();
                    run.message = "Remote Computer sidecar replacement completed but validation controller did not confirm healthy replacement".to_string();
                }
            }
            Err(error) => {
                run.validation_result = json!({
                    "attempted": true,
                    "status": "failed",
                    "error": error.message
                });
                if run.status == "completed" {
                    run.status = "attention".to_string();
                    run.message = "Remote Computer sidecar replacement completed but validation controller failed".to_string();
                }
            }
        }
    }
    state
        .append_audit_log(new_audit_log(
            None,
            "system",
            None,
            "remote_computer.sidecar_recovery_run",
            "remote_computer_sidecar",
            None,
            json!(&run),
        ))
        .await?;
    Ok(run)
}

fn remote_computer_sidecar_validation_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn remote_computer_sidecar_validation_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(false)
}

async fn execute_remote_computer_sidecar_validation_controller<F>(
    lookup: &F,
    run: &RemoteComputerSidecarRecoveryRun,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_VALIDATION_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.remote_computer_sidecar_replacement_validation",
        "generated_at": run.generated_at,
        "status": run.status,
        "validation_controller_required": run.validation_controller_required,
        "unhealthy_count": run.unhealthy_count,
        "planned_replacement_count": run.planned_replacement_count,
        "attempted_replacement_count": run.attempted_replacement_count,
        "blocked_replacement_count": run.blocked_replacement_count,
        "targets": run.targets,
        "runner_response_statuses": run.runner_responses.iter().map(|response| {
            json!({
                "status": response.status,
                "operation": response.operation,
                "pod_name": response.pod_name,
            })
        }).collect::<Vec<_>>(),
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "remote computer sidecar validation controller failed with status {http_status}"
        )));
    }
    let controller_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("validated");
    let validated = matches!(
        controller_status,
        "validated" | "healthy" | "success" | "ok"
    );
    Ok(json!({
        "attempted": true,
        "status": if validated { "validated" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": controller_status,
        "message": body.get("message").and_then(Value::as_str),
        "target_kind": body.get("target_kind").and_then(Value::as_str),
        "cluster_id": body.get("cluster_id").and_then(Value::as_str),
        "cluster_profile": body.get("cluster_profile").and_then(Value::as_str),
        "node_count": body.get("node_count").and_then(Value::as_u64),
        "replacement_scope": body.get("replacement_scope").and_then(Value::as_str),
        "replacement_pods_healthy": body.get("replacement_pods_healthy").and_then(Value::as_bool),
        "checked_pod_count": body.get("checked_pod_count").and_then(Value::as_u64),
    }))
}

async fn build_remote_computer_readiness(
    state: &AppState,
) -> Result<RemoteComputerReadinessReport, AppError> {
    let pod_template =
        remote_computer_manifest_readiness("deploy/k8s/agent-remote-computer.yaml", "pod_template");
    let service_account = remote_computer_manifest_readiness(
        "deploy/k8s/remote-computer-serviceaccount.yaml",
        "service_account",
    );
    let network_policy = remote_computer_manifest_readiness(
        "deploy/k8s/remote-computer-networkpolicy.yaml",
        "network_policy",
    );
    let pvc_path = "deploy/k8s/remote-computer-state-pvc.yaml";
    let state_contract_path = "deploy/k8s/remote-computer-state-contract.yaml";
    let provider_manifest_path = "deploy/k8s/remote-computer-state-juicefs-example.yaml";
    let production_profile_path = "deploy/k8s/remote-computer-state-juicefs-profile.yaml";
    let pvc_present = project_file_path(pvc_path).is_some();
    let state_contract_present = project_file_path(state_contract_path).is_some();
    let state_provider = std::env::var("MANDOFORGE_REMOTE_COMPUTER_STATE_PROVIDER")
        .ok()
        .map(|provider| provider.trim().to_string())
        .filter(|provider| !provider.is_empty())
        .unwrap_or_else(|| "pvc-placeholder".to_string());
    let provider_configured_by_env = state_provider != "pvc-placeholder";
    let provider_manifest_present = project_file_path(provider_manifest_path).is_some();
    let production_profile_present = project_file_path(production_profile_path).is_some();
    let distributed_filesystem_configured = provider_configured_by_env;
    let conflict_policy = std::env::var("MANDOFORGE_REMOTE_COMPUTER_STATE_CONFLICT_POLICY")
        .ok()
        .map(|policy| policy.trim().to_string())
        .filter(|policy| !policy.is_empty())
        .unwrap_or_else(|| "one-active-writer-per-session".to_string());
    let lock_manager_configured = env_bool("MANDOFORGE_REMOTE_COMPUTER_STATE_LOCK_MANAGER");
    let sync_contract_status =
        if distributed_filesystem_configured && state_contract_present && lock_manager_configured {
            "provider_and_lock_manager_configured"
        } else if distributed_filesystem_configured && state_contract_present {
            "provider_configured_without_lock_manager"
        } else if state_contract_present {
            "contract_documented"
        } else {
            "missing"
        }
        .to_string();
    let state_filesystem = RemoteComputerStateFilesystemReadiness {
        pvc_present,
        pvc_path: pvc_path.to_string(),
        access_mode: "ReadWriteMany".to_string(),
        mount_path: "/agent-state".to_string(),
        state_contract_present,
        state_contract_path: state_contract_path.to_string(),
        state_layout_paths: vec![
            "/agent-state/memory".to_string(),
            "/agent-state/notes".to_string(),
            "/agent-state/skills".to_string(),
            "/agent-state/artifacts".to_string(),
            "/agent-state/.locks".to_string(),
            "/agent-state/.mandoforge".to_string(),
        ],
        conflict_policy,
        lock_manager_configured,
        sync_contract_status,
        distributed_filesystem_configured,
        provider: state_provider,
        provider_configured_by_env,
        provider_manifest_present,
        provider_manifest_path: provider_manifest_path.to_string(),
        production_profile_present,
        production_profile_path: production_profile_path.to_string(),
        production_claim_name: "mandoforge-remote-computer-state".to_string(),
        supported_providers: vec![
            "juicefs".to_string(),
            "cephfs".to_string(),
            "longhorn-rwx".to_string(),
            "cloud-file-storage".to_string(),
            "object-sync".to_string(),
        ],
        status: if pvc_present && distributed_filesystem_configured && production_profile_present {
            "configured"
        } else if pvc_present && distributed_filesystem_configured {
            "provider_configured_profile_missing"
        } else if pvc_present && production_profile_present {
            "production_profile_present"
        } else if pvc_present && provider_manifest_present {
            "example_present"
        } else if pvc_present {
            "skeleton"
        } else {
            "missing"
        }
        .to_string(),
    };
    let audit_logs = state.list_audit_logs(None).await.unwrap_or_default();
    let generated_at = Utc::now();
    let production_state_sync = build_remote_computer_production_state_sync_readiness(
        &state_filesystem,
        &audit_logs,
        generated_at,
        remote_computer_state_sync_controller_required(&|key| std::env::var(key).ok()),
        remote_computer_state_sync_controller_configured(&|key| std::env::var(key).ok()),
    );
    let remote_pool_scaled_object_path = "deploy/k8s/remote-computer-keda.yaml";
    let remote_pool_scaled_object_present =
        project_file_path(remote_pool_scaled_object_path).is_some();
    let worker_keda_present = project_file_path("deploy/k8s/worker-keda.yaml").is_some();
    let autoscaling = RemoteComputerAutoscalingReadiness {
        worker_hpa_present: project_file_path("deploy/k8s/worker-hpa.yaml").is_some(),
        keda_manifest_present: project_file_path("deploy/k8s/keda.yaml").is_some()
            || worker_keda_present
            || remote_pool_scaled_object_present,
        remote_pool_scaled_object_present,
        remote_pool_scaled_object_path: remote_pool_scaled_object_path.to_string(),
        queue_depth_scaling_present: remote_pool_scaled_object_present,
        status: if remote_pool_scaled_object_present {
            "remote_pool_scaler_example_present"
        } else if worker_keda_present {
            "worker_queue_scaling_present"
        } else if project_file_path("deploy/k8s/worker-hpa.yaml").is_some() {
            "hpa_skeleton"
        } else {
            "missing"
        }
        .to_string(),
    };
    let warm_pool_path = "deploy/k8s/remote-computer-warm-pool.yaml";
    let warm_pool_manifest_present = project_file_path(warm_pool_path).is_some();
    let warm_pool = RemoteComputerWarmPoolReadiness {
        configured: std::env::var("MANDOFORGE_REMOTE_COMPUTER_WARM_POOL")
            .ok()
            .is_some_and(|value| value == "1" || value.eq_ignore_ascii_case("true")),
        manifest_present: warm_pool_manifest_present,
        manifest_path: warm_pool_path.to_string(),
        status: if warm_pool_manifest_present {
            "skeleton"
        } else {
            "missing"
        }
        .to_string(),
    };
    let artifact_discovery_sidecar = remote_computer_manifest_readiness(
        "deploy/k8s/remote-computer-artifact-discovery-sidecar.yaml",
        "artifact_discovery_sidecar",
    );
    let artifact_discovery_sidecar_config =
        remote_computer_artifact_discovery_sidecar_config_readiness();
    let sidecar_supervision =
        build_remote_computer_sidecar_supervision(state, artifact_discovery_sidecar.present)
            .await?;
    let runner = build_remote_computer_runner_readiness();
    let sidecar_recovery_targets = remote_computer_sidecar_recovery_targets(state).await?;
    let sidecar_recovery =
        build_remote_computer_sidecar_recovery_readiness(&sidecar_recovery_targets, &runner);
    let execution_transport = build_remote_computer_execution_transport_readiness(state).await?;

    let event_types = vec![
        "remote_computer.requested".to_string(),
        "remote_computer.leased".to_string(),
        "remote_computer.started".to_string(),
        "remote_computer.heartbeat".to_string(),
        "remote_computer.attached".to_string(),
        "remote_computer.warm_pool_claimed".to_string(),
        "remote_computer.execution_handoff_planned".to_string(),
        "remote_computer.execution_handoff_assigned".to_string(),
        "remote_computer.execution_handoff_acknowledged".to_string(),
        "remote_computer.execution_handoff_completed".to_string(),
        "remote_computer.execution_handoff_released".to_string(),
        "remote_computer.execution_handoff_failed".to_string(),
        "remote_computer.execution_handoff_canceled".to_string(),
        "remote_computer.state_lock_acquired".to_string(),
        "remote_computer.state_lock_released".to_string(),
        "remote_computer.sidecar_heartbeat".to_string(),
        "remote_computer.execution_transport_planned".to_string(),
        "remote_computer.execution_transport_completed".to_string(),
        "remote_computer.runner_dry_run".to_string(),
        "remote_computer.artifact_discovered".to_string(),
        "remote_computer.detached".to_string(),
        "remote_computer.attachment_reclaimed".to_string(),
        "remote_computer.lease_reclaimed".to_string(),
        "remote_computer.released".to_string(),
        "remote_computer.failed".to_string(),
    ];
    let mut attention_items = Vec::new();
    if !pod_template.present {
        attention_items.push(remote_computer_attention(
            "pod_template_missing",
            "critical",
            "deploy/k8s/agent-remote-computer.yaml is required before Pod-based session leases can be piloted",
        ));
    }
    if !service_account.present {
        attention_items.push(remote_computer_attention(
            "service_account_missing",
            "critical",
            "remote computer Pods need a restricted service account before execution moves into Pods",
        ));
    }
    if state_filesystem.status == "missing" {
        attention_items.push(remote_computer_attention(
            "state_pvc_missing",
            "critical",
            "remote computer state PVC placeholder is missing",
        ));
    } else if !state_filesystem.state_contract_present {
        attention_items.push(remote_computer_attention(
            "state_contract_missing",
            "critical",
            "remote computer Memory/Notes/Skills state contract ConfigMap is missing",
        ));
    } else if state_filesystem.provider_configured_by_env
        && !state_filesystem.production_profile_present
    {
        attention_items.push(remote_computer_attention(
            "distributed_state_profile_missing",
            "critical",
            "remote computer state provider is configured, but the production state filesystem profile manifest is missing",
        ));
    } else if !state_filesystem.distributed_filesystem_configured {
        attention_items.push(remote_computer_attention(
            "distributed_state_filesystem_missing",
            "warning",
            "state mount has a PVC/RWX placeholder and optional JuiceFS production profile; set a real JuiceFS/CephFS/Longhorn or equivalent provider before multi-Pod state sync",
        ));
    }
    if production_state_sync.production_blocked {
        attention_items.push(remote_computer_attention(
            "production_state_sync_blocked",
            "critical",
            production_state_sync.message.as_str(),
        ));
    }
    if !network_policy.present {
        attention_items.push(remote_computer_attention(
            "network_policy_missing",
            "warning",
            "remote computer Pods need a NetworkPolicy before shared-cluster sandbox execution",
        ));
    }
    if !autoscaling.queue_depth_scaling_present {
        attention_items.push(remote_computer_attention(
            "queue_depth_scaling_missing",
            "warning",
            "worker HPA is present as a skeleton, but KEDA/queue-depth scaling for remote computer pools is not configured",
        ));
    }
    if !warm_pool.manifest_present {
        attention_items.push(remote_computer_attention(
            "warm_pool_missing",
            "warning",
            "no remote computer warm-pool manifest is present; first Pod lease will still cold start",
        ));
    }
    if !artifact_discovery_sidecar.present {
        attention_items.push(remote_computer_attention(
            "artifact_discovery_sidecar_missing",
            "warning",
            "remote computer Pods need an artifact discovery sidecar before continuous artifact sync can be piloted",
        ));
    } else if artifact_discovery_sidecar_config.status != "configured" {
        attention_items.push(remote_computer_attention(
            "artifact_discovery_sidecar_api_url_mismatch",
            "warning",
            "remote computer artifact discovery sidecar must target the in-cluster mandoforge-api service on port 8787",
        ));
    } else if sidecar_supervision.missing_heartbeat_count > 0 {
        attention_items.push(remote_computer_attention(
            "artifact_discovery_sidecar_heartbeat_missing",
            "warning",
            "one or more active remote computers have no artifact-discovery sidecar heartbeat",
        ));
    }
    if sidecar_supervision.stale_heartbeat_count > 0 {
        attention_items.push(remote_computer_attention(
            "artifact_discovery_sidecar_heartbeat_stale",
            "warning",
            "one or more artifact-discovery sidecar heartbeats are older than the configured stale threshold",
        ));
    }
    if sidecar_recovery.status == "blocked" {
        attention_items.push(remote_computer_attention(
            "sidecar_replacement_blocked",
            "warning",
            "Remote Computer sidecar recovery found unhealthy sidecars, but replacement automation is blocked",
        ));
    }
    if !runner.configured {
        attention_items.push(remote_computer_attention(
            "runner_reserved",
            "warning",
            "Remote Computer runner is fail-closed; Kubernetes Pod create/delete is dry-run only",
        ));
    }
    if !execution_transport.execution_enabled {
        attention_items.push(remote_computer_attention(
            "pod_execution_transport_disabled",
            "warning",
            "Remote Computer job handoff can be planned and audited, but approved tools still execute on the existing worker path",
        ));
    }

    let mut runbook_actions = Vec::new();
    if !state_filesystem.distributed_filesystem_configured {
        runbook_actions.push(
            "set MANDOFORGE_REMOTE_COMPUTER_STATE_PROVIDER to juicefs, cephfs, longhorn-rwx, or an equivalent provider before running multi-Pod Memory/Notes/Skills sync"
                .to_string(),
        );
    }
    if state_filesystem.production_profile_present {
        runbook_actions.push(
            "apply deploy/k8s/remote-computer-state-juicefs-profile.yaml only after replacing placeholder JuiceFS metadata, object storage, and access credentials"
                .to_string(),
        );
    }
    if !state_filesystem.lock_manager_configured {
        runbook_actions.push(
            "keep shared Memory/Notes/Skills read-mostly and route writes through runtime APIs until a lock-aware sync manager is configured"
                .to_string(),
        );
    }
    if !autoscaling.queue_depth_scaling_present {
        runbook_actions.push(
            "add or enable deploy/k8s/remote-computer-keda.yaml before claiming remote computer pool autoscaling"
                .to_string(),
        );
    }
    if !warm_pool.manifest_present {
        runbook_actions.push(
            "add a warm-pool controller only after the Pod lease lifecycle and state sync are observable"
                .to_string(),
        );
    }
    if artifact_discovery_sidecar.present {
        runbook_actions.push(
            "monitor /api/remote-computers/sidecars/heartbeats and treat stale or missing artifact-discovery heartbeats as Remote Computer pilot blockers"
                .to_string(),
        );
        runbook_actions.push(
            "run /api/remote-computers/sidecars/recovery/run to produce an audited Pod replacement plan; enable MANDOFORGE_REMOTE_COMPUTER_SIDECAR_REPLACEMENT_ENABLED only after Kubernetes runner live mutation gates are validated"
                .to_string(),
        );
    }
    runbook_actions.push(
        "keep unassigned jobs on the existing approved worker path until Remote Computer lease assignment is production-hardened"
            .to_string(),
    );
    runbook_actions.push(
        "use /api/remote-computers/runner/dry-run to inspect Pod runner intent without mutating Kubernetes"
            .to_string(),
    );
    runbook_actions.push(
        "use /api/remote-computers/artifacts/discover for shared-workspace artifact scans, and keep sidecar-driven continuous discovery as a production hardening task"
            .to_string(),
    );
    runbook_actions.push(
        "enable MANDOFORGE_REMOTE_COMPUTER_EXECUTION_ENABLED only for explicit Kubernetes Pod exec pilots with approved shell.exec/codex.exec jobs"
            .to_string(),
    );
    runbook_actions.push(
        "run /api/remote-computers/reclaim-stale to clear stale attachment and expired lease records without executing tools"
            .to_string(),
    );

    let critical_count = attention_items
        .iter()
        .filter(|item| item.severity == "critical")
        .count() as i64;
    let warning_count = attention_items
        .iter()
        .filter(|item| item.severity == "warning")
        .count() as i64;
    let readiness_score = (100_i64 - critical_count * 25 - warning_count * 10).clamp(0, 100);
    let status = if critical_count > 0 {
        "critical"
    } else if warning_count > 0 {
        "attention"
    } else {
        "ready"
    }
    .to_string();

    Ok(RemoteComputerReadinessReport {
        generated_at,
        status,
        readiness_score,
        pod_template,
        service_account,
        state_filesystem,
        production_state_sync,
        network_policy,
        autoscaling,
        warm_pool,
        artifact_discovery_sidecar,
        artifact_discovery_sidecar_config,
        sidecar_supervision,
        sidecar_recovery,
        runner,
        execution_transport,
        event_types,
        attention_items,
        runbook_actions,
    })
}

fn remote_computer_state_sync_base_issues(
    state_filesystem: &RemoteComputerStateFilesystemReadiness,
) -> Vec<String> {
    let mut blocking_reasons = Vec::new();
    if !state_filesystem.distributed_filesystem_configured {
        blocking_reasons.push(
            "no real distributed filesystem provider is configured for multi-Pod state sync"
                .to_string(),
        );
    }
    if !state_filesystem.production_profile_present {
        blocking_reasons.push(
            "production state filesystem profile manifest is missing or not packaged".to_string(),
        );
    }
    if !state_filesystem.state_contract_present {
        blocking_reasons.push("Memory/Notes/Skills state contract is missing".to_string());
    }
    if !state_filesystem.lock_manager_configured {
        blocking_reasons
            .push("lock-aware state sync manager is not configured for shared writes".to_string());
    }
    if state_filesystem.conflict_policy != "one-active-writer-per-session" {
        blocking_reasons.push(
            "state conflict policy is not the expected one-active-writer contract".to_string(),
        );
    }
    blocking_reasons
}

fn remote_computer_state_sync_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_REMOTE_COMPUTER_STATE_SYNC_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(false)
}

fn remote_computer_state_sync_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_REMOTE_COMPUTER_STATE_SYNC_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

async fn execute_remote_computer_state_sync_controller<F>(
    lookup: &F,
    subject: &str,
    checked_at: DateTime<Utc>,
    state_filesystem: &RemoteComputerStateFilesystemReadiness,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_REMOTE_COMPUTER_STATE_SYNC_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request(
                "MANDOFORGE_REMOTE_COMPUTER_STATE_SYNC_CONTROLLER_URL is required",
            )
        })?;
    let timeout_seconds = lookup("MANDOFORGE_REMOTE_COMPUTER_STATE_SYNC_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_REMOTE_COMPUTER_STATE_SYNC_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.remote_computer_state_sync_validation",
        "subject": subject,
        "checked_at": checked_at,
        "provider": state_filesystem.provider,
        "distributed_filesystem_configured": state_filesystem.distributed_filesystem_configured,
        "production_profile_present": state_filesystem.production_profile_present,
        "state_contract_present": state_filesystem.state_contract_present,
        "lock_manager_configured": state_filesystem.lock_manager_configured,
        "conflict_policy": state_filesystem.conflict_policy,
        "mount_path": state_filesystem.mount_path,
        "state_layout_paths": state_filesystem.state_layout_paths,
        "production_claim_name": state_filesystem.production_claim_name,
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "remote computer state sync controller failed with status {http_status}"
        )));
    }
    let provider_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("validated");
    let validated = matches!(provider_status, "validated" | "healthy" | "success" | "ok");
    Ok(json!({
        "attempted": true,
        "status": if validated { "validated" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": provider_status,
        "state_sync_id": body.get("state_sync_id").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "target_kind": body.get("target_kind").and_then(Value::as_str),
        "cluster_id": body.get("cluster_id").and_then(Value::as_str),
        "cluster_profile": body.get("cluster_profile").and_then(Value::as_str),
        "node_count": body.get("node_count").and_then(Value::as_u64),
        "distributed_state_backend": body
            .get("distributed_state_backend")
            .or_else(|| body.get("storage_backend"))
            .or_else(|| body.get("state_backend"))
            .and_then(Value::as_str),
        "state_claim": body.get("state_claim").and_then(Value::as_str),
        "checked_path_count": body.get("checked_path_count").and_then(Value::as_u64),
    }))
}

fn build_remote_computer_production_state_sync_readiness(
    state_filesystem: &RemoteComputerStateFilesystemReadiness,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> RemoteComputerProductionStateSyncReadiness {
    let mut blocking_reasons = remote_computer_state_sync_base_issues(state_filesystem);
    let latest_validation = audit_logs
        .iter()
        .filter(|log| log.action == "remote_computer.production_state_sync_validation")
        .max_by_key(|log| log.created_at);
    let latest_validation_at = latest_validation.map(|log| log.created_at);
    let latest_validation_status = latest_validation
        .and_then(|log| log.details.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_status = latest_validation
        .and_then(|log| log.details.get("controller_execution"))
        .and_then(|execution| execution.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_age_hours = latest_validation
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    if controller_required && !controller_configured {
        blocking_reasons.push("state sync controller is required but not configured".to_string());
    }
    if controller_required && latest_validation.is_none() {
        blocking_reasons.push("state sync validation has not run".to_string());
    }
    if latest_validation_at.is_some_and(|created_at| (generated_at - created_at).num_hours() >= 24)
    {
        blocking_reasons.push("state sync validation evidence is stale".to_string());
    }
    if controller_required && controller_configured && !latest_controller_validated {
        blocking_reasons
            .push("state sync controller evidence is missing or not validated".to_string());
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("state sync controller evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Remote Computer production state sync is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Remote Computer production state sync has a distributed filesystem provider, production profile, state contract, and lock-aware write coordination".to_string()
    };

    RemoteComputerProductionStateSyncReadiness {
        status,
        production_blocked,
        distributed_filesystem_configured: state_filesystem.distributed_filesystem_configured,
        production_profile_present: state_filesystem.production_profile_present,
        state_contract_present: state_filesystem.state_contract_present,
        lock_manager_configured: state_filesystem.lock_manager_configured,
        controller_required,
        controller_configured,
        latest_validation_at,
        latest_validation_status,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        conflict_policy: state_filesystem.conflict_policy.clone(),
        provider: state_filesystem.provider.clone(),
        blocking_reasons,
        message,
    }
}

async fn build_remote_computer_execution_transport_readiness(
    state: &AppState,
) -> Result<RemoteComputerExecutionTransportReadiness, AppError> {
    let assignments = state.list_remote_computer_job_assignments().await?;
    let assignment_count = assignments.len();
    let active_assignment_count = assignments
        .iter()
        .filter(|assignment| assignment.status == "assigned")
        .count();
    let mode = std::env::var("MANDOFORGE_REMOTE_COMPUTER_EXECUTION_TRANSPORT")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "reserved".to_string());
    let requested_execution_enabled = env_bool("MANDOFORGE_REMOTE_COMPUTER_EXECUTION_ENABLED");
    let (execution_enabled, status) =
        remote_computer_execution_transport_state(&mode, requested_execution_enabled);
    let required_implementation = if execution_enabled {
        Vec::new()
    } else {
        vec![
            "automatic artifact discovery sidecar ID injection and production supervision"
                .to_string(),
        ]
    };
    let message = if execution_enabled {
        "Remote Computer assigned-Pod execution is enabled for approved file.write, shell.exec, and codex.exec jobs through the worker, policy, approval, event, and audit paths"
    } else {
        "Remote Computer runner can plan assigned Pod execution fail-closed; enable Kubernetes transport gates only after runner, state sync, and sidecar evidence are ready"
    };
    Ok(RemoteComputerExecutionTransportReadiness {
        mode,
        requested_execution_enabled,
        execution_enabled,
        status: status.to_string(),
        assignment_count,
        active_assignment_count,
        supported_operations: vec![
            "plan_pod_exec_intent".to_string(),
            "runner_live_exec_websocket".to_string(),
            "assigned_file_write".to_string(),
            "assigned_shell_exec".to_string(),
            "assigned_codex_exec".to_string(),
            "cancel_assigned_pod_exec".to_string(),
            "push_remote_artifacts_to_artifact_store".to_string(),
            "discover_remote_artifacts_from_shared_workspace".to_string(),
            "audit_handoff".to_string(),
            "fail_closed".to_string(),
        ],
        required_implementation,
        message: message.to_string(),
    })
}

fn remote_computer_execution_transport_state(
    mode: &str,
    requested_execution_enabled: bool,
) -> (bool, &'static str) {
    let normalized_mode = mode.trim().to_ascii_lowercase();
    if requested_execution_enabled && matches!(normalized_mode.as_str(), "kubernetes" | "k8s") {
        (true, "enabled")
    } else if matches!(normalized_mode.as_str(), "kubernetes" | "k8s") {
        (false, "blocked")
    } else {
        (false, "reserved")
    }
}

fn sidecar_stale_after_seconds() -> i64 {
    env_i64("MANDOFORGE_REMOTE_COMPUTER_SIDECAR_STALE_AFTER_SECONDS")
        .filter(|seconds| *seconds > 0)
        .unwrap_or(180)
}

async fn build_remote_computer_sidecar_supervision(
    state: &AppState,
    sidecar_manifest_present: bool,
) -> Result<RemoteComputerSidecarSupervisionReadiness, AppError> {
    let active_remote_computers: Vec<_> = state
        .list_remote_computers()
        .await?
        .into_iter()
        .filter(|computer| matches!(computer.status.as_str(), "available" | "leased" | "running"))
        .collect();
    let heartbeats = state.list_remote_computer_sidecar_heartbeats().await?;
    let stale_after_seconds = sidecar_stale_after_seconds();
    let now = Utc::now();
    let mut latest_by_remote: HashMap<Uuid, RemoteComputerSidecarHeartbeat> = HashMap::new();
    for heartbeat in heartbeats.iter().filter(|heartbeat| {
        heartbeat.sidecar_name == "artifact-discovery" && heartbeat.status != "disabled"
    }) {
        latest_by_remote
            .entry(heartbeat.remote_computer_id)
            .and_modify(|existing| {
                if heartbeat.observed_at > existing.observed_at {
                    *existing = heartbeat.clone();
                }
            })
            .or_insert_with(|| heartbeat.clone());
    }
    let missing_heartbeat_count = active_remote_computers
        .iter()
        .filter(|computer| !latest_by_remote.contains_key(&computer.id))
        .count();
    let stale_heartbeat_count = active_remote_computers
        .iter()
        .filter_map(|computer| latest_by_remote.get(&computer.id))
        .filter(|heartbeat| {
            now.signed_duration_since(heartbeat.observed_at)
                .num_seconds()
                > stale_after_seconds
        })
        .count();
    let latest_observed_at = latest_by_remote
        .values()
        .map(|heartbeat| heartbeat.observed_at)
        .max();
    let status = if !sidecar_manifest_present {
        "manifest_missing"
    } else if missing_heartbeat_count > 0 || stale_heartbeat_count > 0 {
        "attention"
    } else if !latest_by_remote.is_empty() {
        "observed"
    } else {
        "not_observed"
    }
    .to_string();
    Ok(RemoteComputerSidecarSupervisionReadiness {
        status,
        heartbeat_count: heartbeats.len(),
        active_remote_computer_count: active_remote_computers.len(),
        missing_heartbeat_count,
        stale_heartbeat_count,
        stale_after_seconds,
        latest_observed_at,
    })
}

async fn remote_computer_sidecar_recovery_targets(
    state: &AppState,
) -> Result<Vec<RemoteComputerSidecarRecoveryTarget>, AppError> {
    let active_remote_computers: Vec<_> = state
        .list_remote_computers()
        .await?
        .into_iter()
        .filter(|computer| matches!(computer.status.as_str(), "available" | "leased" | "running"))
        .collect();
    let heartbeats = state.list_remote_computer_sidecar_heartbeats().await?;
    let stale_after_seconds = sidecar_stale_after_seconds();
    let now = Utc::now();
    let mut latest_by_remote: HashMap<Uuid, RemoteComputerSidecarHeartbeat> = HashMap::new();
    for heartbeat in heartbeats.iter().filter(|heartbeat| {
        heartbeat.sidecar_name == "artifact-discovery" && heartbeat.status != "disabled"
    }) {
        latest_by_remote
            .entry(heartbeat.remote_computer_id)
            .and_modify(|existing| {
                if heartbeat.observed_at > existing.observed_at {
                    *existing = heartbeat.clone();
                }
            })
            .or_insert_with(|| heartbeat.clone());
    }
    let mut targets = Vec::new();
    for computer in active_remote_computers {
        match latest_by_remote.get(&computer.id) {
            None => targets.push(RemoteComputerSidecarRecoveryTarget {
                remote_computer_id: computer.id,
                name: computer.name,
                pod_name: computer.pod_name,
                reason: "missing_artifact_discovery_heartbeat".to_string(),
                latest_observed_at: None,
            }),
            Some(heartbeat)
                if now
                    .signed_duration_since(heartbeat.observed_at)
                    .num_seconds()
                    > stale_after_seconds =>
            {
                targets.push(RemoteComputerSidecarRecoveryTarget {
                    remote_computer_id: computer.id,
                    name: computer.name,
                    pod_name: computer.pod_name,
                    reason: "stale_artifact_discovery_heartbeat".to_string(),
                    latest_observed_at: Some(heartbeat.observed_at),
                });
            }
            Some(_) => {}
        }
    }
    Ok(targets)
}

fn build_remote_computer_sidecar_recovery_readiness(
    targets: &[RemoteComputerSidecarRecoveryTarget],
    runner: &RemoteComputerRunnerReadiness,
) -> RemoteComputerSidecarRecoveryReadiness {
    build_remote_computer_sidecar_recovery_readiness_with_lookup(targets, runner, &|key| {
        std::env::var(key).ok()
    })
}

fn build_remote_computer_sidecar_recovery_readiness_with_lookup<F>(
    targets: &[RemoteComputerSidecarRecoveryTarget],
    runner: &RemoteComputerRunnerReadiness,
    lookup: &F,
) -> RemoteComputerSidecarRecoveryReadiness
where
    F: Fn(&str) -> Option<String>,
{
    let replacement_enabled = env_bool_lookup(
        "MANDOFORGE_REMOTE_COMPUTER_SIDECAR_REPLACEMENT_ENABLED",
        lookup,
    );
    let validation_controller_required =
        remote_computer_sidecar_validation_controller_required(lookup);
    let validation_controller_configured =
        remote_computer_sidecar_validation_controller_configured(lookup);
    let replaceable_pod_count = targets
        .iter()
        .filter(|target| target.pod_name.is_some())
        .count();
    let blocked_reason = if targets.is_empty() {
        None
    } else if !replacement_enabled {
        Some("replacement_gate_disabled".to_string())
    } else if !runner.configured {
        Some("runner_not_configured".to_string())
    } else if !runner.live_mutation_enabled {
        Some("runner_live_mutation_disabled".to_string())
    } else if replaceable_pod_count < targets.len() {
        Some("unhealthy_remote_computer_missing_pod_name".to_string())
    } else if validation_controller_required && !validation_controller_configured {
        Some("validation_controller_required".to_string())
    } else {
        None
    };
    let status = if targets.is_empty() {
        "ready"
    } else if blocked_reason.is_some() {
        "blocked"
    } else {
        "ready_to_replace"
    };
    let message = if targets.is_empty() {
        "No unhealthy Remote Computer sidecars require Pod replacement".to_string()
    } else if let Some(reason) = &blocked_reason {
        format!("Remote Computer sidecar replacement is blocked by {reason}")
    } else {
        "Remote Computer sidecar replacement gate is open for unhealthy Pods".to_string()
    };
    RemoteComputerSidecarRecoveryReadiness {
        status: status.to_string(),
        replacement_enabled,
        validation_controller_required,
        validation_controller_configured,
        runner_configured: runner.configured,
        runner_live_mutation_enabled: runner.live_mutation_enabled,
        unhealthy_count: targets.len(),
        replaceable_pod_count,
        blocked_reason,
        message,
    }
}

fn env_bool(name: &str) -> bool {
    env_bool_lookup(name, &|key| std::env::var(key).ok())
}

fn env_bool_lookup<F>(name: &str, lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup(name)
        .map(|value| {
            let normalized = value.trim().to_ascii_lowercase();
            matches!(normalized.as_str(), "1" | "true" | "yes" | "on")
        })
        .unwrap_or(false)
}

fn build_remote_computer_runner_readiness() -> RemoteComputerRunnerReadiness {
    let config = RemoteComputerRunnerConfig::from_env();
    let runner = remote_computer_runner_for_config(&config);
    runner.readiness(&config)
}

