    fn env_lock() -> &'static Mutex<()> {
        static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
        LOCK.get_or_init(|| Mutex::new(()))
    }

    struct EnvVarGuard {
        key: &'static str,
        previous: Option<String>,
    }

    impl EnvVarGuard {
        fn set(key: &'static str, value: &str) -> Self {
            let previous = std::env::var(key).ok();
            unsafe {
                std::env::set_var(key, value);
            }
            Self { key, previous }
        }

        fn remove(key: &'static str) -> Self {
            let previous = std::env::var(key).ok();
            unsafe {
                std::env::remove_var(key);
            }
            Self { key, previous }
        }
    }

    impl Drop for EnvVarGuard {
        fn drop(&mut self) {
            unsafe {
                if let Some(previous) = self.previous.as_ref() {
                    std::env::set_var(self.key, previous);
                } else {
                    std::env::remove_var(self.key);
                }
            }
        }
    }

    #[test]
    fn allows_read_only_sql() {
        assert!(
            ensure_read_only_sql("select * from generic_demo.platform_events limit 10").is_ok()
        );
        assert!(ensure_read_only_sql("with daily as (select 1) select * from daily").is_ok());
        assert!(ensure_read_only_sql("explain select * from generic_demo.platform_events").is_ok());
    }

    #[test]
    fn rejects_write_sql() {
        for sql in [
            "update products set price = price * 0.9",
            "delete from orders",
            "drop table orders",
            "insert into products values ('x')",
            "select * from orders; delete from orders;",
        ] {
            assert!(ensure_read_only_sql(sql).is_err(), "{sql}");
        }
    }

    #[test]
    fn runtime_tenant_id_defaults_and_parses_env_override() {
        let default_tenant = runtime_tenant_id_from_lookup(|_| None).expect("default tenant id");
        assert_eq!(
            default_tenant,
            Uuid::parse_str(DEFAULT_TENANT_ID).expect("valid default tenant id")
        );

        let configured_tenant = Uuid::parse_str("00000000-0000-4000-8000-000000000042")
            .expect("valid configured tenant id");
        let parsed = runtime_tenant_id_from_lookup(|key| {
            if key == "MANDOFORGE_TENANT_ID" {
                Some(format!(" {configured_tenant} "))
            } else {
                None
            }
        })
        .expect("configured tenant id");
        assert_eq!(parsed, configured_tenant);

        let error = runtime_tenant_id_from_lookup(|key| {
            if key == "MANDOFORGE_TENANT_ID" {
                Some("not-a-uuid".to_string())
            } else {
                None
            }
        })
        .expect_err("invalid tenant id should fail closed");
        assert!(
            error
                .to_string()
                .contains("MANDOFORGE_TENANT_ID must be a valid UUID")
        );
    }

    #[test]
    fn tenant_runtime_mode_defaults_and_parses_env_override() {
        assert_eq!(
            tenant_runtime_mode_from_lookup(|_| None).expect("default tenant mode"),
            TenantRuntimeMode::SingleRuntimeTenant
        );
        assert_eq!(
            tenant_runtime_mode_from_lookup(|key| {
                (key == "MANDOFORGE_TENANT_ROUTING_MODE").then(|| "tenant_routed".to_string())
            })
            .expect("tenant routed mode"),
            TenantRuntimeMode::TenantRouted
        );
        let error = tenant_runtime_mode_from_lookup(|key| {
            (key == "MANDOFORGE_TENANT_ROUTING_MODE").then(|| "unsafe".to_string())
        })
        .expect_err("unsupported tenant mode should fail closed");
        assert!(
            error
                .to_string()
                .contains("unsupported MANDOFORGE_TENANT_ROUTING_MODE")
        );
    }

    #[test]
    fn stage2_readiness_parses_open_completion_gaps() {
        let audit = r#"
# Stage 2 Completion Audit

## Open Completion Gaps

1. First production blocker.
2. Second controller-backed blocker.

## Completion Decision

Stage 2 is not complete.
"#;

        let gaps = parse_stage2_open_gaps(audit);

        assert_eq!(gaps.len(), 2);
        assert_eq!(gaps[0], "First production blocker.");
        assert_eq!(gaps[1], "Second controller-backed blocker.");

        let readiness = build_stage2_completion_readiness();
        assert_eq!(readiness.evidence_requirements.len(), 13);
        assert_eq!(readiness.evidence_requirements[0].id, "tenant-routing");
        assert!(
            readiness.evidence_requirements[0]
                .validation_endpoints
                .contains(&"/api/tenant-isolation/routing/validate".to_string())
        );
        assert!(
            readiness.evidence_requirements[0]
                .evidence_scripts
                .contains(&"./scripts/tenant-isolation-evidence-gate.sh".to_string())
        );
        assert!(
            readiness.evidence_requirements[0]
                .evidence_job_manifests
                .contains(
                    &"deploy/stage2-evidence/tenant-isolation-evidence-job.example.yaml"
                        .to_string()
                )
        );
        assert!(
            readiness
                .evidence_requirements
                .iter()
                .any(|requirement| requirement.id == "ui-production-polish")
        );

        let mcp = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "mcp-rollout")
            .expect("missing MCP rollout evidence requirement");
        assert!(
            mcp.required_flags
                .contains(&"RUN_STAGE2_MCP_DUE_RUN=1".to_string())
        );
        assert!(
            mcp.required_flags
                .contains(&"RUN_STAGE2_MCP_ROLLBACK=1".to_string())
        );
        assert!(
            mcp.evidence_job_manifests.contains(
                &"deploy/stage2-evidence/mcp-gateway-evidence-job.example.yaml".to_string()
            )
        );

        let eval_release = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "eval-release")
            .expect("missing eval release evidence requirement");
        assert!(
            eval_release
                .required_flags
                .contains(&"RUN_STAGE2_EVAL_RELEASE_AUTOMATION=1".to_string())
        );
        assert!(
            eval_release
                .required_flags
                .contains(&"RUN_STAGE2_EVAL_RELEASE_ROLLBACK=1".to_string())
        );

        let managed_session = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "managed-session-restart-resume")
            .expect("missing managed-session restart/resume evidence requirement");
        assert!(
            managed_session
                .required_flags
                .contains(&"RUN_STAGE2_MANAGED_SESSION_RESTART_RESUME=1".to_string())
        );
        assert!(
            managed_session.required_flags.contains(
                &"MANDOFORGE_STAGE2_MANAGED_SESSION_RUNTIME_TARGET_ID=managed-session-runtime-prod"
                    .to_string()
            )
        );
        assert!(
            managed_session
                .required_artifacts
                .contains(&"managed-session-restart-resume-evidence.json".to_string())
        );

        let finance = readiness
            .evidence_requirements
            .iter()
            .find(|requirement| requirement.id == "finance-close")
            .expect("missing finance evidence requirement");
        assert!(
            finance
                .required_flags
                .contains(&"RUN_STAGE2_FINANCE_CONTROLLERS=1".to_string())
        );
        assert!(
            finance
                .required_flags
                .contains(&"RUN_STAGE2_FINANCE_EXPORT=1".to_string())
        );
        assert!(finance.required_flags.contains(
            &"FINANCE_EXPORT_DELIVERY_OBSERVER_URL=https://controller.example.com/mandoforge/finance/export/observer"
                .to_string()
        ));
        assert!(
            finance
                .required_artifacts
                .contains(&"finance-export-delivery-observer.json".to_string())
        );
    }

    #[test]
    fn stage2_readiness_evidence_metadata_matches_repo_contract() {
        let root = repo_root();
        let readiness = build_stage2_completion_readiness();
        let production_gate = read_repo_file(&root, "scripts/stage2-production-evidence-gate.sh");
        let completion_audit = read_repo_file(&root, "scripts/stage2-completion-audit-gate.sh");
        let controller_env = read_repo_file(
            &root,
            "deploy/stage2-evidence/stage2-production-controllers.env.example",
        );
        let controller_secret = read_repo_file(
            &root,
            "deploy/stage2-evidence/stage2-controller-env-secret.example.yaml",
        );

        for requirement in &readiness.evidence_requirements {
            assert!(
                !requirement.evidence_scripts.is_empty(),
                "{} must declare evidence scripts",
                requirement.id
            );
            assert!(
                !requirement.evidence_job_manifests.is_empty(),
                "{} must declare evidence Job manifests",
                requirement.id
            );
            assert!(
                !requirement.required_artifacts.is_empty(),
                "{} must declare required evidence artifacts",
                requirement.id
            );

            let mut focused_sources = String::new();
            for script in &requirement.evidence_scripts {
                let script_path = repo_path(&root, script);
                assert!(
                    script_path.is_file(),
                    "{} declares missing evidence script {}",
                    requirement.id,
                    script
                );
                assert_executable(&script_path, script);
                focused_sources.push_str(&read_repo_file(&root, script));
                focused_sources.push('\n');
            }

            for manifest in &requirement.evidence_job_manifests {
                let manifest_path = repo_path(&root, manifest);
                assert!(
                    manifest_path.is_file(),
                    "{} declares missing evidence Job manifest {}",
                    requirement.id,
                    manifest
                );
                let manifest_source = read_repo_file(&root, manifest);
                assert!(
                    manifest_source.contains("claimName: mandoforge-stage2-production-evidence"),
                    "{} manifest {} must persist evidence to the production PVC",
                    requirement.id,
                    manifest
                );
            }

            for required_flag in &requirement.required_flags {
                let flag_name = required_flag
                    .split_once('=')
                    .map_or(required_flag.as_str(), |(name, _)| name);
                assert!(
                    controller_env.contains(&format!("{flag_name}=")),
                    "{} required flag {} is missing from controller env example",
                    requirement.id,
                    flag_name
                );
                assert!(
                    controller_secret.contains(&format!("{flag_name}:")),
                    "{} required flag {} is missing from controller Secret example",
                    requirement.id,
                    flag_name
                );
            }

            let endpoint_artifacts = requirement
                .readiness_endpoints
                .iter()
                .chain(requirement.validation_endpoints.iter())
                .filter(|endpoint| !endpoint.starts_with("./"))
                .map(|endpoint| format!("{}.json", slugify_for_stage2_evidence(endpoint)))
                .collect::<Vec<_>>();
            let local_script_artifacts = requirement
                .evidence_scripts
                .iter()
                .map(|script| {
                    format!(
                        "local-script-{}.json",
                        slugify_for_stage2_evidence(script.trim_start_matches("./"))
                    )
                })
                .collect::<Vec<_>>();

            for artifact in &requirement.required_artifacts {
                let has_literal_writer = focused_sources.contains(artifact)
                    || production_gate.contains(artifact)
                    || completion_audit.contains(artifact);
                let has_endpoint_writer = endpoint_artifacts
                    .iter()
                    .any(|candidate| candidate == artifact);
                let has_local_script_writer = local_script_artifacts
                    .iter()
                    .any(|candidate| candidate == artifact);
                assert!(
                    has_literal_writer || has_endpoint_writer || has_local_script_writer,
                    "{} required artifact {} is not backed by a focused script, strict gate endpoint capture, or local-script capture",
                    requirement.id,
                    artifact
                );
            }
        }
    }

    fn repo_root() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .expect("api crate must live under crates/mandoforge-api")
            .to_path_buf()
    }

    fn repo_path(root: &Path, relative: &str) -> PathBuf {
        root.join(relative.trim_start_matches("./"))
    }

    fn read_repo_file(root: &Path, relative: &str) -> String {
        let path = repo_path(root, relative);
        fs::read_to_string(&path)
            .unwrap_or_else(|error| panic!("failed to read {}: {error}", path.display()))
    }

    #[cfg(unix)]
    fn assert_executable(path: &Path, label: &str) {
        let mode = fs::metadata(path)
            .unwrap_or_else(|error| panic!("failed to stat {}: {error}", path.display()))
            .permissions()
            .mode();
        assert!(
            mode & 0o111 != 0,
            "evidence script {label} must be executable"
        );
    }

    #[cfg(not(unix))]
    fn assert_executable(path: &Path, _label: &str) {
        assert!(path.is_file());
    }

    fn slugify_for_stage2_evidence(value: &str) -> String {
        let mut output = String::new();
        let mut previous_separator = false;
        for ch in value.trim_start_matches('/').chars() {
            if ch == '/' || ch == ':' {
                if !previous_separator {
                    output.push('-');
                    previous_separator = true;
                }
            } else if ch.is_ascii_alphanumeric() || ch == '.' || ch == '_' || ch == '-' {
                output.push(ch);
                previous_separator = false;
            } else {
                if !previous_separator {
                    output.push('-');
                    previous_separator = true;
                }
            }
        }
        output
    }

    #[test]
    fn registry_contains_allowed_stage1_tools() {
        let registry = tool_registry();
        for expected in [
            "artifact.create",
            "approval.request",
            "file.read",
            "sql.get_schema",
            "sql.query",
        ] {
            assert!(registry.contains_key(expected), "missing {expected}");
        }

        let descriptors = tool_descriptors();
        for expected in ["file.write", "shell.exec", "codex.exec"] {
            assert!(
                descriptors
                    .iter()
                    .any(|descriptor| descriptor.name == expected),
                "missing descriptor {expected}"
            );
        }
    }

