    #[test]
    fn session_statuses_use_managed_agent_lifecycle_names() {
        assert_eq!(SessionStatus::Idle.as_str(), "idle");
        assert_eq!(SessionStatus::RequiresAction.as_str(), "requires_action");
        assert_eq!(SessionStatus::Rescheduling.as_str(), "rescheduling");
        assert_eq!(SessionStatus::Terminated.as_str(), "terminated");

        assert_eq!(
            SessionStatus::from("created".to_string()),
            SessionStatus::Idle
        );
        assert_eq!(
            SessionStatus::from("waiting_approval".to_string()),
            SessionStatus::RequiresAction
        );
        assert_eq!(
            SessionStatus::from("completed".to_string()),
            SessionStatus::Terminated
        );
    }

    #[test]
    fn tenant_rls_migration_covers_tracked_tables() {
        let migration = format!(
            "{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}",
            include_str!("../../../db/migrations/0024_tenant_rls_policies.sql"),
            include_str!("../../../db/migrations/0025_remote_computer_state_locks.sql"),
            include_str!("../../../db/migrations/0026_remote_computer_sidecar_heartbeats.sql"),
            include_str!("../../../db/migrations/0027_agent_handoff_events.sql"),
            include_str!("../../../db/migrations/0028_workflow_pack_installations.sql"),
            include_str!("../../../db/migrations/0029_workflow_pack_profile_assets.sql"),
            include_str!("../../../db/migrations/0030_agent_runtime_profiles.sql"),
            include_str!("../../../db/migrations/0032_manager_agent_plans.sql"),
            include_str!("../../../db/migrations/0034_agent_handoff_assignments.sql"),
            include_str!("../../../db/migrations/0035_semantic_kernel.sql"),
            include_str!("../../../db/migrations/0036_context_packets.sql"),
            include_str!("../../../db/migrations/0037_memory_writeback_candidates.sql"),
            include_str!("../../../db/migrations/0038_environments.sql"),
            include_str!("../../../db/migrations/0039_session_loop_jobs.sql"),
            include_str!("../../../db/migrations/0040_session_threads.sql")
        );
        assert!(migration.contains("mandoforge_current_tenant_id"));
        assert!(migration.contains("FORCE ROW LEVEL SECURITY"));
        for table in tenant_isolation_tracked_tables() {
            assert!(
                migration.contains(&format!("'{table}'"))
                    || (table == "agent_versions"
                        && migration.contains("tenant_isolation_agent_versions")),
                "RLS migration should mention tracked tenant table {table}"
            );
        }
    }

    #[tokio::test]
    async fn remote_computer_leases_are_audited_without_executing_tools() {
        let app = test_app().await;
        let agents: Vec<Agent> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/agents")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let session: Session = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/sessions")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({"agent_id": agents[0].id, "title": "remote computer lease"}).to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        let computer: RemoteComputer = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/remote-computers")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "name": "remote-computer-test",
                        "profile": "workspace-write",
                        "pod_name": "agent-remote-computer-0"
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(computer.status, "available");

        let lease: RemoteComputerLease = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/remote-computers/{}/leases", computer.id))
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "session_id": session.id,
                        "worker_id": "remote-manager-1",
                        "lease_seconds": 120,
                        "metadata": {"execution_enabled": false}
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(lease.status, "leased");
        assert_eq!(lease.session_id, Some(session.id));
        assert!(lease.lease_expires_at.is_some());

        let heartbeat: RemoteComputerLease = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!(
                    "/api/remote-computer-leases/{}/heartbeat",
                    lease.id
                ))
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({"metadata": {"heartbeat": true}}).to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(heartbeat.status, "leased");
        assert_eq!(heartbeat.metadata["heartbeat"], true);

        let released: RemoteComputerLease = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/remote-computer-leases/{}/release", lease.id))
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({"reason": "readiness skeleton release"}).to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        assert_eq!(released.status, "released");
        assert_eq!(released.metadata["reason"], "readiness skeleton release");

        let leases: Vec<RemoteComputerLease> = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/remote-computer-leases")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(leases.len(), 1);

        let events: Vec<SessionEvent> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/events", session.id))
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        let event_types: Vec<_> = events
            .iter()
            .map(|event| event.event_type.as_str())
            .collect();
        assert!(event_types.contains(&"remote_computer.leased"));
        assert!(event_types.contains(&"remote_computer.heartbeat"));
        assert!(event_types.contains(&"remote_computer.released"));

        let tool_calls: Vec<ToolCall> = request_json(
            app.clone(),
            Request::builder()
                .uri(format!("/api/sessions/{}/tool-calls", session.id))
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            tool_calls.is_empty(),
            "remote computer lease lifecycle must not execute tools"
        );

        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri(format!("/api/sessions/{}/audit-logs", session.id))
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(
            audit_logs
                .iter()
                .any(|log| log.action == "remote_computer.leased")
        );
        assert!(
            audit_logs
                .iter()
                .any(|log| log.action == "remote_computer.released")
        );
    }

