    fn test_policy_body(http_allowed: bool) -> Value {
        let approval_required = if http_allowed {
            json!([
                {"tool": "shell.exec", "risk": "high"},
                {"tool": "codex.exec", "risk": "high"},
                {"tool": "file.write", "risk": "medium"}
            ])
        } else {
            json!([
                {"tool": "shell.exec", "risk": "high"},
                {"tool": "codex.exec", "risk": "high"},
                {"tool": "file.write", "risk": "medium"},
                {"tool": "http.request", "risk": "high"}
            ])
        };
        json!({
            "blocked_tools": ["secret.read"],
            "approval_required": approval_required,
            "allowed_tools": {
                "generic-orchestrator-agent": ["file.read", "file.write", "sql.get_schema", "sql.query", "shell.exec", "codex.exec", "approval.request", "artifact.create", "mcp.call", "http.request"]
            },
            "sql_policy": {
                "max_rows": 500,
                "blocked_keywords": ["INSERT", "UPDATE", "DELETE", "DROP"]
            }
        })
    }

    #[tokio::test]
    async fn staged_policy_rollout_selects_candidate_by_session_bucket() {
        let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
        let staged_policy = serde_json::from_value::<PolicyConfig>(json!({
            "blocked_tools": ["secret.read"],
            "approval_required": [
                {"tool": "shell.exec", "risk": "high"},
                {"tool": "codex.exec", "risk": "high"},
                {"tool": "file.write", "risk": "medium"}
            ],
            "allowed_tools": {
                "generic-orchestrator-agent": ["file.read", "file.write", "sql.get_schema", "sql.query", "shell.exec", "codex.exec", "approval.request", "artifact.create", "mcp.call", "http.request"]
            },
            "sql_policy": {
                "max_rows": 500,
                "blocked_keywords": ["INSERT", "UPDATE", "DELETE", "DROP"]
            }
        }))
        .expect("policy");
        state
            .activate_runtime_policy(Uuid::new_v4(), staged_policy, 1)
            .await;

        let candidate_session = Uuid::from_u128(0);
        let baseline_session = Uuid::from_u128(99);
        assert_eq!(
            state
                .policy_for_session(candidate_session)
                .await
                .evaluate_tool("http.request")
                .decision,
            "allowed"
        );
        assert_eq!(
            state
                .policy_for_session(baseline_session)
                .await
                .evaluate_tool("http.request")
                .decision,
            "requires_approval"
        );
    }

    #[tokio::test]
    async fn principal_auth_fails_closed_without_dev_auth() {
        let _env_guard = env_lock().lock().expect("env lock");
        let _insecure_auth = EnvVarGuard::set("MANDOFORGE_INSECURE_DEV_AUTH", "0");
        let _dev_token = EnvVarGuard::remove("MANDOFORGE_DEV_ADMIN_TOKEN");
        let _tenant_trust = EnvVarGuard::remove("MANDOFORGE_TRUST_X_MANDOFORGE_TENANT_ID");
        let _subject_trust = EnvVarGuard::remove("MANDOFORGE_TRUST_X_MANDOFORGE_SUBJECT");
        let state = test_state_with_worker(Arc::new(InlineExecutionWorker));

        let missing_subject = principal_from_request(&state, &HeaderMap::new())
            .await
            .expect_err("missing subject should fail closed");
        assert_eq!(missing_subject.status, StatusCode::UNAUTHORIZED);

        let mut forged_roles = HeaderMap::new();
        forged_roles.insert("x-mandoforge-subject", "admin-1".parse().unwrap());
        forged_roles.insert("x-mandoforge-roles", "admin".parse().unwrap());
        let forged_error = principal_from_request(&state, &forged_roles)
            .await
            .expect_err("client-forged subject should be rejected");
        assert_eq!(forged_error.status, StatusCode::UNAUTHORIZED);

        let _subject_trust = EnvVarGuard::set("MANDOFORGE_TRUST_X_MANDOFORGE_SUBJECT", "1");
        let trusted_subject_forged_roles_error = principal_from_request(&state, &forged_roles)
            .await
            .expect_err("trusted subject ingress still rejects client-forged roles");
        assert_eq!(
            trusted_subject_forged_roles_error.status,
            StatusCode::FORBIDDEN
        );

        let mut trusted_subject = HeaderMap::new();
        trusted_subject.insert("x-mandoforge-subject", "admin-1".parse().unwrap());
        let trusted_subject_without_membership = principal_from_request(&state, &trusted_subject)
            .await
            .expect_err("trusted subject ingress still requires membership roles");
        assert_eq!(
            trusted_subject_without_membership.status,
            StatusCode::FORBIDDEN
        );
    }

    #[tokio::test]
    async fn tenant_routed_header_requires_trusted_ingress() {
        let _env_guard = env_lock().lock().expect("env lock");
        let _insecure_auth = EnvVarGuard::set("MANDOFORGE_INSECURE_DEV_AUTH", "0");
        let tenant_trust = EnvVarGuard::remove("MANDOFORGE_TRUST_X_MANDOFORGE_TENANT_ID");
        let mut state = test_state_with_worker(Arc::new(InlineExecutionWorker));
        state.tenant_runtime_mode = TenantRuntimeMode::TenantRouted;
        let mut headers = HeaderMap::new();
        headers.insert(
            "x-mandoforge-tenant-id",
            Uuid::new_v4().to_string().parse().unwrap(),
        );

        let error = resolve_request_tenant_id(&state, &headers)
            .expect_err("untrusted tenant header should fail closed");
        assert_eq!(error.status, StatusCode::FORBIDDEN);

        drop(tenant_trust);
        let _tenant_trust = EnvVarGuard::set("MANDOFORGE_TRUST_X_MANDOFORGE_TENANT_ID", "1");
        assert!(resolve_request_tenant_id(&state, &headers).is_ok());
    }

